-- Sinkronkan master PI dari tabel legacy setelah PI yang hilang ditambahkan.
INSERT IGNORE INTO `database_master_pi` (`kontrak_id`,`nomor_pi`,`nomor_po_lama`,`tanggal_pi_text`,`judul_kontrak`)
SELECT k.`id`, p.`Proforma Invoice No.`, NULLIF(TRIM(p.`Nomor Purchase Order`), ''),
       NULLIF(TRIM(p.`Tanggal Performa Invoice`), ''), NULLIF(TRIM(p.`Judul Kontrak`), '')
FROM `database_proforma_invoice` p JOIN `master_kontrak` k
  ON CONVERT(k.`nomor_kontrak` USING utf8mb4) COLLATE utf8mb4_unicode_ci =
     CONVERT(TRIM(CAST(p.`Nomor Kontrak` AS CHAR)) USING utf8mb4) COLLATE utf8mb4_unicode_ci
WHERE p.`Proforma Invoice No.` IS NOT NULL AND TRIM(p.`Proforma Invoice No.`) NOT IN ('', '-', '0');

