-- Jaga judul PI ternormalisasi tetap mengikuti header PI yang sudah diselaraskan.
UPDATE `database_master_pi` mp
JOIN `master_kontrak` k ON k.`id` = mp.`kontrak_id`
JOIN `database_proforma_invoice` p
  ON CONVERT(p.`Nomor Kontrak` USING utf8mb4) COLLATE utf8mb4_unicode_ci =
     CONVERT(k.`nomor_kontrak` USING utf8mb4) COLLATE utf8mb4_unicode_ci
 AND CONVERT(p.`Proforma Invoice No.` USING utf8mb4) COLLATE utf8mb4_unicode_ci =
     CONVERT(mp.`nomor_pi` USING utf8mb4) COLLATE utf8mb4_unicode_ci
SET mp.`judul_kontrak` = p.`Judul Kontrak`
WHERE NOT (
    CONVERT(mp.`judul_kontrak` USING utf8mb4) COLLATE utf8mb4_unicode_ci
    <=> CONVERT(p.`Judul Kontrak` USING utf8mb4) COLLATE utf8mb4_unicode_ci
);

COMMIT;
